/**
 * Estimates a realistic IPA phonetic transcription for an English word
 * when an explicit IPA string is not provided.
 */
export function estimateIpaPhonetics(word: string): { uk: string; us: string } {
  const clean = word.toLowerCase().replace(/[^a-z-]/g, '');
  if (!clean) return { uk: '/-/', us: '/-/' };

  let ipa = clean
    .replace(/tion$/g, 'ʃən')
    .replace(/sion$/g, 'ʒən')
    .replace(/cian$/g, 'ʃən')
    .replace(/ture$/g, 'tʃə')
    .replace(/sure$/g, 'ʒə')
    .replace(/ious$/g, 'i.əs')
    .replace(/eous$/g, 'i.əs')
    .replace(/ous$/g, 'əs')
    .replace(/ment$/g, 'mənt')
    .replace(/ness$/g, 'nəs')
    .replace(/able$/g, 'ə.bəl')
    .replace(/ible$/g, 'ə.bəl')
    .replace(/ology$/g, 'ˈɒl.ə.dʒi')
    .replace(/logical$/g, 'ˈlɒdʒ.ɪ.kəl')
    .replace(/graphic$/g, 'ˈɡræf.ɪk')
    .replace(/graphy$/g, 'ɡrə.fi')
    .replace(/metry$/g, 'mə.tri')
    .replace(/meter$/g, 'miː.tə')
    .replace(/ight/g, 'aɪt')
    .replace(/ough/g, 'ʌf')
    .replace(/ph/g, 'f')
    .replace(/sh/g, 'ʃ')
    .replace(/ch/g, 'tʃ')
    .replace(/th/g, 'θ')
    .replace(/qu/g, 'kw')
    .replace(/ck/g, 'k')
    .replace(/ng/g, 'ŋ')
    .replace(/ee/g, 'iː')
    .replace(/ea/g, 'iː')
    .replace(/oo/g, 'uː')
    .replace(/ou/g, 'aʊ')
    .replace(/ow/g, 'əʊ')
    .replace(/ai/g, 'eɪ')
    .replace(/ay/g, 'eɪ')
    .replace(/oi/g, 'ɔɪ')
    .replace(/oy/g, 'ɔɪ')
    .replace(/au/g, 'ɔː')
    .replace(/aw/g, 'ɔː')
    .replace(/ar/g, 'ɑː')
    .replace(/or/g, 'ɔː')
    .replace(/er$/g, 'ə')
    .replace(/ir/g, 'ɜː')
    .replace(/ur/g, 'ɜː')
    .replace(/y$/g, 'i');

  const uk = `/${ipa}/`;
  const us = `/${ipa.replace(/ɒ/g, 'ɑː').replace(/ə$/g, 'ər')}/`;
  return { uk, us };
}

function tupleToCorpusEntry(tuple: [string, string, string, string?], word: string): CorpusDictEntry {
  const [cn, pos, en, ipa] = tuple;
  if (ipa) {
    const usIpa = ipa.replace(/ɒ/g, 'ɑː').replace(/ɑː(?!r)/g, 'ɑːr').replace(/ɔː(?!r)/g, 'ɔːr');
    return { cn, pos, en, uk: ipa, us: usIpa };
  }
  const estimated = estimateIpaPhonetics(word);
  return { cn, pos, en, uk: estimated.uk, us: estimated.us };
}

/**
 * Generates candidate base/root lemmas for an inflected or derived English word.
 */
function getLemmaCandidates(lower: string): Array<{ base: string; suffixType: string }> {
  const candidates: Array<{ base: string; suffixType: string }> = [];

  if (lower.endsWith('ies') && lower.length > 4) {
    candidates.push({ base: lower.slice(0, -3) + 'y', suffixType: 'plural_or_3sg' });
  }
  if (lower.endsWith('ves') && lower.length > 4) {
    candidates.push({ base: lower.slice(0, -3) + 'f', suffixType: 'plural' });
    candidates.push({ base: lower.slice(0, -3) + 'fe', suffixType: 'plural' });
  }
  if (lower.endsWith('es') && lower.length > 3) {
    candidates.push({ base: lower.slice(0, -2), suffixType: 'plural_or_3sg' });
    candidates.push({ base: lower.slice(0, -1), suffixType: 'plural_or_3sg' });
  }
  if (lower.endsWith('s') && !lower.endsWith('ss') && !lower.endsWith('us') && !lower.endsWith('is') && lower.length > 3) {
    candidates.push({ base: lower.slice(0, -1), suffixType: 'plural_or_3sg' });
  }
  if (lower.endsWith('ied') && lower.length > 4) {
    candidates.push({ base: lower.slice(0, -3) + 'y', suffixType: 'past' });
  }
  if (lower.endsWith('ed') && lower.length > 4) {
    const stem = lower.slice(0, -2);
    candidates.push({ base: stem, suffixType: 'past' });
    candidates.push({ base: lower.slice(0, -1), suffixType: 'past' });
    if (stem.length > 2 && stem[stem.length - 1] === stem[stem.length - 2]) {
      candidates.push({ base: stem.slice(0, -1), suffixType: 'past' });
    }
  }
  if (lower.endsWith('ing') && lower.length > 5) {
    const stem = lower.slice(0, -3);
    candidates.push({ base: stem, suffixType: 'gerund' });
    candidates.push({ base: stem + 'e', suffixType: 'gerund' });
    if (stem.length > 2 && stem[stem.length - 1] === stem[stem.length - 2]) {
      candidates.push({ base: stem.slice(0, -1), suffixType: 'gerund' });
    }
  }
  if (lower.endsWith('ally') && lower.length > 6) {
    candidates.push({ base: lower.slice(0, -4), suffixType: 'adv' });
    candidates.push({ base: lower.slice(0, -2), suffixType: 'adv' });
  }
  if (lower.endsWith('ily') && lower.length > 5) {
    candidates.push({ base: lower.slice(0, -3) + 'y', suffixType: 'adv' });
  }
  if (lower.endsWith('ly') && lower.length > 4) {
    candidates.push({ base: lower.slice(0, -2), suffixType: 'adv' });
    candidates.push({ base: lower.slice(0, -2) + 'e', suffixType: 'adv' });
  }
  if (lower.endsWith('er') && lower.length > 4) {
    const stem = lower.slice(0, -2);
    candidates.push({ base: stem, suffixType: 'er' });
    candidates.push({ base: stem + 'e', suffixType: 'er' });
    if (stem.length > 2 && stem[stem.length - 1] === stem[stem.length - 2]) {
      candidates.push({ base: stem.slice(0, -1), suffixType: 'er' });
    }
  }
  if (lower.endsWith('est') && lower.length > 5) {
    const stem = lower.slice(0, -3);
    candidates.push({ base: stem, suffixType: 'est' });
    candidates.push({ base: stem + 'e', suffixType: 'est' });
    if (stem.length > 2 && stem[stem.length - 1] === stem[stem.length - 2]) {
      candidates.push({ base: stem.slice(0, -1), suffixType: 'est' });
    }
  }
  if (lower.endsWith('ation') && lower.length > 6) {
    candidates.push({ base: lower.slice(0, -5) + 'e', suffixType: 'noun' });
    candidates.push({ base: lower.slice(0, -5), suffixType: 'noun' });
    candidates.push({ base: lower.slice(0, -3) + 'e', suffixType: 'noun' });
  }
  if (lower.endsWith('tion') && lower.length > 5) {
    candidates.push({ base: lower.slice(0, -4) + 'te', suffixType: 'noun' });
    candidates.push({ base: lower.slice(0, -4) + 't', suffixType: 'noun' });
    candidates.push({ base: lower.slice(0, -3) + 'e', suffixType: 'noun' });
  }
  if (lower.endsWith('ment') && lower.length > 5) {
    candidates.push({ base: lower.slice(0, -4), suffixType: 'noun' });
  }
  if (lower.endsWith('ness') && lower.length > 5) {
    candidates.push({ base: lower.slice(0, -4), suffixType: 'noun' });
    if (lower.endsWith('iness')) {
      candidates.push({ base: lower.slice(0, -5) + 'y', suffixType: 'noun' });
    }
  }
  if (lower.endsWith('ity') && lower.length > 5) {
    candidates.push({ base: lower.slice(0, -3), suffixType: 'noun' });
    candidates.push({ base: lower.slice(0, -3) + 'e', suffixType: 'noun' });
  }
  if (lower.endsWith('able') && lower.length > 5) {
    candidates.push({ base: lower.slice(0, -4), suffixType: 'adj' });
    candidates.push({ base: lower.slice(0, -4) + 'e', suffixType: 'adj' });
  }
  if (lower.endsWith('ive') && lower.length > 5) {
    candidates.push({ base: lower.slice(0, -3), suffixType: 'adj' });
    candidates.push({ base: lower.slice(0, -3) + 'e', suffixType: 'adj' });
  }
  if (lower.endsWith('al') && lower.length > 4) {
    candidates.push({ base: lower.slice(0, -2), suffixType: 'adj' });
    candidates.push({ base: lower.slice(0, -2) + 'e', suffixType: 'adj' });
  }
  if (lower.endsWith('ic') && lower.length > 4) {
    candidates.push({ base: lower.slice(0, -2), suffixType: 'adj' });
    candidates.push({ base: lower.slice(0, -2) + 'y', suffixType: 'adj' });
  }
  if (lower.endsWith('ist') && lower.length > 5) {
    candidates.push({ base: lower.slice(0, -3), suffixType: 'ist' });
    candidates.push({ base: lower.slice(0, -3) + 'y', suffixType: 'ist' });
    candidates.push({ base: lower.slice(0, -3) + 'e', suffixType: 'ist' });
  }

  return candidates;
}

const ACADEMIC_PREFIXES: Array<{ prefix: string; cnPrefix: string; enPrefix: string }> = [
  { prefix: 're-', cnPrefix: '重新/再', enPrefix: 'Again or anew: ' },
  { prefix: 're', cnPrefix: '重新/再', enPrefix: 'Again or anew: ' },
  { prefix: 'un-', cnPrefix: '未/不/非', enPrefix: 'Not or reversed: ' },
  { prefix: 'un', cnPrefix: '未/不/非', enPrefix: 'Not or reversed: ' },
  { prefix: 'non-', cnPrefix: '非/无', enPrefix: 'Not or free from: ' },
  { prefix: 'non', cnPrefix: '非/无', enPrefix: 'Not or free from: ' },
  { prefix: 'pre-', cnPrefix: '预先/前', enPrefix: 'Before or prior to: ' },
  { prefix: 'pre', cnPrefix: '预先/前', enPrefix: 'Before or prior to: ' },
  { prefix: 'post-', cnPrefix: '后/……之后的', enPrefix: 'After or subsequent to: ' },
  { prefix: 'micro-', cnPrefix: '微/微观', enPrefix: 'Micro-scale or microscopic: ' },
  { prefix: 'micro', cnPrefix: '微/微观', enPrefix: 'Micro-scale or microscopic: ' },
  { prefix: 'macro-', cnPrefix: '宏观/大型', enPrefix: 'Large-scale or macroscopic: ' },
  { prefix: 'multi-', cnPrefix: '多/多重', enPrefix: 'Multiple or many: ' },
  { prefix: 'multi', cnPrefix: '多/多重', enPrefix: 'Multiple or many: ' },
  { prefix: 'sub-', cnPrefix: '次/亚/地下/下层', enPrefix: 'Under, below, or secondary: ' },
  { prefix: 'sub', cnPrefix: '次/亚/地下/下层', enPrefix: 'Under, below, or secondary: ' },
  { prefix: 'super-', cnPrefix: '超/特级', enPrefix: 'Above, beyond, or extreme: ' },
  { prefix: 'super', cnPrefix: '超/特级', enPrefix: 'Above, beyond, or extreme: ' },
  { prefix: 'over-', cnPrefix: '过度/上方', enPrefix: 'Excessively or above: ' },
  { prefix: 'over', cnPrefix: '过度/上方', enPrefix: 'Excessively or above: ' },
  { prefix: 'under-', cnPrefix: '不足/下方', enPrefix: 'Below or insufficiently: ' },
  { prefix: 'under', cnPrefix: '不足/下方', enPrefix: 'Below or insufficiently: ' },
  { prefix: 'out', cnPrefix: '超越/胜过', enPrefix: 'Surpassing or exceeding: ' },
  { prefix: 'bio-', cnPrefix: '生物/生态', enPrefix: 'Biological or life-related: ' },
  { prefix: 'bio', cnPrefix: '生物/生态', enPrefix: 'Biological or life-related: ' },
  { prefix: 'eco-', cnPrefix: '生态/环保', enPrefix: 'Ecological or environmentally friendly: ' },
  { prefix: 'geo-', cnPrefix: '地球/地质', enPrefix: 'Geological or Earth-related: ' },
  { prefix: 'hydro-', cnPrefix: '水/水力/氢', enPrefix: 'Water or fluid-related: ' },
  { prefix: 'thermo-', cnPrefix: '热/温控', enPrefix: 'Heat or temperature-related: ' },
  { prefix: 'neuro-', cnPrefix: '神经/脑科学', enPrefix: 'Neural or nervous-system related: ' },
  { prefix: 'neuro', cnPrefix: '神经/脑科学', enPrefix: 'Neural or nervous-system related: ' },
  { prefix: 'electro-', cnPrefix: '电/电磁', enPrefix: 'Electrical or electromagnetic: ' },
  { prefix: 'trans-', cnPrefix: '跨/横穿/转换', enPrefix: 'Across or beyond: ' },
  { prefix: 'self-', cnPrefix: '自我/自动', enPrefix: 'By or of oneself/itself: ' },
  { prefix: 'co-', cnPrefix: '共同/协同', enPrefix: 'Jointly or mutually: ' },
  { prefix: 'inter-', cnPrefix: '跨/相互', enPrefix: 'Between or among: ' },
  { prefix: 'counter-', cnPrefix: '反/逆向', enPrefix: 'Contrary or opposing: ' }
];

/**
 * Looks up a word in the IELTS Corpus Dictionary with full morphological
 * lemmatization, prefix-root synthesis, and hyphenated compound resolution.
 */
export function lookupInIeltsCorpus(rawWord: string): CorpusDictEntry | null {
  const lower = rawWord.toLowerCase().trim().replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, '');
  if (!lower) return null;

  // 1. Direct exact hit
  if (IELTS_CORPUS_TUPLES[lower]) {
    return tupleToCorpusEntry(IELTS_CORPUS_TUPLES[lower], lower);
  }

  // 2. American <-> British spelling normalization
  const spellingVariants = [
    lower.replace(/our$/g, 'or'),
    lower.replace(/or$/g, 'our'),
    lower.replace(/ise$/g, 'ize'),
    lower.replace(/ize$/g, 'ise'),
    lower.replace(/ising$/g, 'izing'),
    lower.replace(/izing$/g, 'ising'),
    lower.replace(/ised$/g, 'ized'),
    lower.replace(/ized$/g, 'ised'),
    lower.replace(/isation$/g, 'ization'),
    lower.replace(/ization$/g, 'isation'),
    lower.replace(/re$/g, 'er'),
    lower.replace(/lling$/g, 'ling'),
    lower.replace(/ling$/g, 'lling'),
    lower.replace(/lled$/g, 'led'),
    lower.replace(/led$/g, 'lled')
  ];
  for (const variant of spellingVariants) {
    if (variant !== lower && IELTS_CORPUS_TUPLES[variant]) {
      return tupleToCorpusEntry(IELTS_CORPUS_TUPLES[variant], lower);
    }
  }

  // 3. Spelled-out surname or letter sequence (e.g. "h-e-n-d-e-r-s-o-n" or "m-a-y-a")
  if (/^[a-z](?:-[a-z]){2,}$/.test(lower)) {
    const joined = lower.replace(/-/g, '');
    const joinedCap = joined.charAt(0).toUpperCase() + joined.slice(1);
    const baseHit = IELTS_CORPUS_TUPLES[joined];
    return {
      cn: baseHit ? `${baseHit[0]}（字母拼写：${lower.toUpperCase()}）` : `${joinedCap}（专有名词/姓名拼写：${lower.toUpperCase()}）`,
      pos: 'n. 专有名词拼写',
      en: `Spelled-out proper name or key term: ${joinedCap} (${lower.toUpperCase()}).`,
      uk: estimateIpaPhonetics(joined).uk,
      us: estimateIpaPhonetics(joined).us
    };
  }

  // 4. Lemma / Suffix inflection resolution
  const candidates = getLemmaCandidates(lower);
  for (const { base, suffixType } of candidates) {
    const tuple = IELTS_CORPUS_TUPLES[base];
    if (tuple) {
      const baseEntry = tupleToCorpusEntry(tuple, lower);
      const cleanBaseCn = baseEntry.cn.split(/[；，]/)[0];
      if (suffixType === 'adv') {
        return {
          cn: `${cleanBaseCn}地`,
          pos: 'adv. 副词',
          en: `In a manner related to ${base}: ${baseEntry.en}`,
          uk: estimateIpaPhonetics(lower).uk,
          us: estimateIpaPhonetics(lower).us
        };
      }
      if (suffixType === 'past') {
        return {
          cn: `${baseEntry.cn}（${base} 的过去式/分词）`,
          pos: 'v. / adj.',
          en: `${baseEntry.en} (past tense or past participle of "${base}").`,
          uk: estimateIpaPhonetics(lower).uk,
          us: estimateIpaPhonetics(lower).us
        };
      }
      if (suffixType === 'gerund') {
        return {
          cn: `${baseEntry.cn}（${base} 的现在分词/动名词）`,
          pos: 'n. / v.',
          en: `${baseEntry.en} (present participle or gerund of "${base}").`,
          uk: estimateIpaPhonetics(lower).uk,
          us: estimateIpaPhonetics(lower).us
        };
      }
      if (suffixType === 'er') {
        return {
          cn: `更${cleanBaseCn}；${cleanBaseCn}者/器`,
          pos: 'adj. / n.',
          en: `Comparative form or agent of "${base}": ${baseEntry.en}`,
          uk: estimateIpaPhonetics(lower).uk,
          us: estimateIpaPhonetics(lower).us
        };
      }
      if (suffixType === 'est') {
        return {
          cn: `最${cleanBaseCn}`,
          pos: 'adj. 最高级',
          en: `Superlative form of "${base}": ${baseEntry.en}`,
          uk: estimateIpaPhonetics(lower).uk,
          us: estimateIpaPhonetics(lower).us
        };
      }
      if (suffixType === 'ist') {
        return {
          cn: `${cleanBaseCn}学家，${cleanBaseCn}专业人员`,
          pos: 'n. 名词',
          en: `A specialist or practitioner in ${base}: ${baseEntry.en}`,
          uk: estimateIpaPhonetics(lower).uk,
          us: estimateIpaPhonetics(lower).us
        };
      }
      return {
        cn: baseEntry.cn,
        pos: baseEntry.pos,
        en: baseEntry.en,
        uk: estimateIpaPhonetics(lower).uk,
        us: estimateIpaPhonetics(lower).us
      };
    }
  }

  // 5. Hyphenated compound word resolution (e.g. "sodium-ion", "thirty-five", "termite-inspired")
  if (lower.includes('-')) {
    const parts = lower.split('-').filter(Boolean);
    if (parts.length >= 2) {
      const resolvedParts = parts.map(p => lookupInIeltsCorpus(p));
      if (resolvedParts.some(Boolean)) {
        const cnParts = parts.map((p, idx) => {
          const hit = resolvedParts[idx];
          if (!hit) return p;
          return hit.cn.split(/[；，、（(]/)[0].replace(/的$/, '');
        });
        const ph = estimateIpaPhonetics(lower);
        return {
          cn: `${cnParts.join('-')}（复合词）`,
          pos: 'adj. / n. 复合词',
          en: `Compound term combining ${parts.map(p => `"${p}"`).join(' and ')}.`,
          uk: ph.uk,
          us: ph.us
        };
      }
    }
  }

  // 6. Academic prefix + root composition (e.g., "rewilded", "subglacial", "outperforming")
  for (const { prefix, cnPrefix, enPrefix } of ACADEMIC_PREFIXES) {
    if (lower.startsWith(prefix) && lower.length > prefix.length + 2) {
      const remainder = lower.slice(prefix.length).replace(/^-/, '');
      const rootEntry = lookupInIeltsCorpus(remainder);
      if (rootEntry) {
        const cleanRootCn = rootEntry.cn.split(/[；，、（(]/)[0];
        const ph = estimateIpaPhonetics(lower);
        return {
          cn: `${cnPrefix}${cleanRootCn}`,
          pos: rootEntry.pos,
          en: `${enPrefix}${rootEntry.en}`,
          uk: ph.uk,
          us: ph.us
        };
      }
    }
  }

  return null;
}
